def cmd_last(args):
    filepath=parse_file_arg(args)
    all_entries, errors = load_activities_or_error(filepath, False)
    for err in errors:
        print(f"Warning: Ignoring line {err['line_num']}. Please see `bartib check` for further information")
    valid=[a for a in all_entries if a['valid']]
    valid_sorted=sorted(valid, key=lambda x: x['start'], reverse=True)
    seen=set()
    deduped=[]
    for a in valid_sorted:
        key=(a['description'], a['project'])
        if key not in seen:
            seen.add(key)
            deduped.append(a)
    if not deduped:
        print("No activities have been tracked yet")
        return
    try:
        n=int(args.number)
    except:
        n=10
    deduped=deduped[:n]
    max_desc=max(len(a['description']) for a in deduped) if deduped else 0
    max_proj=max(len(a['project']) for a in deduped) if deduped else 0
    desc_width=max(len("Description"), max_desc)
    proj_width=max(len("Project"), max_proj)
    def pad(s,w):
        return s + NBSP*(w - len(s)) if len(s) < w else s
    print("")
    print(f"{underline(pad(' #'+NBSP,3))} {underline(pad('Description', desc_width))} {underline(pad('Project', proj_width))} ")
    display=list(reversed(deduped))
    for pos, act in enumerate(display):
        idx=len(deduped)-1 - pos
        print(f"[{idx}] {pad(act['description'], desc_width)} {pad(act['project'], proj_width)} ")
    print("")

def cmd_search(args):
