def cmd_sanity(args):
    filepath=parse_file_arg(args)
    all_entries, errors = load_activities_or_error(filepath, False)
    valid=[a for a in all_entries if a['valid']]
    valid_sorted=sorted(valid, key=lambda x: x['start'])
    issues=[]
    for a in valid_sorted:
        if a['end'] and a['end'] < a['start']:
            issues.append(f"Activity has negative duration\n{a['description']} (Started: {a['start'].strftime('%Y-%m-%d %H:%M')}, Ended: {a['end'].strftime('%Y-%m-%d %H:%M')}, Line: {a['line_num']})\n")
    now=get_now()
    for i in range(1, len(valid_sorted)):
        prev=valid_sorted[i-1]
        curr=valid_sorted[i]
        prev_end=prev['end'] if prev['end'] else now
        if curr['start'] < prev_end:
            issues.append(f"Activity started before another activity ended\n{curr['description']} (Started: {curr['start'].strftime('%Y-%m-%d %H:%M')}, Ended: {curr['end'].strftime('%Y-%m-%d %H:%M') if curr['end'] else '-'}, Line: {curr['line_num']})\n")
    if not issues:
        print("No unusual activities.")
    else:
        for iss in issues:
            print(iss)

def cmd_status(args):
    filepath=parse_file_arg(args)
    all_entries, errors = load_activities_or_error(filepath, False)
    for err in errors:
        print(f"Warning: Ignoring line {err['line_num']}. Please see `bartib check` for further information")
    valid=[a for a in all_entries if a['valid']]
    filter_proj=getattr(args, 'project', None)
    if filter_proj:
        filtered=[a for a in valid if a['project']==filter_proj]
        display_name=filter_proj
        is_all=False
    else:
        filtered=valid
        display_name="ALL"
        is_all=True
    running=[a for a in filtered if a['end'] is None]
    now=get_now()
    today=get_today()
    monday_current=today - datetime.timedelta(days=today.weekday())
    first_month=today.replace(day=1)
    today_total=sum(compute_duration(a, now) for a in filtered if a['start'].date()==today)
    week_total=sum(compute_duration(a, now) for a in filtered if a['start'].date()>=monday_current)
    month_total=sum(compute_duration(a, now) for a in filtered if a['start'].date()>=first_month)

    DIM=ANSI_DIM
    ITALIC=ANSI_ITALIC
    BOLD=ANSI_BOLD
    RESET=ANSI_RESET
    BOLD_GREEN=ANSI_BOLD_GREEN
    DIM_ITALIC="\x1b[2;3m"

    if is_all:
        print(f"{DIM}\n ======={RESET}{ITALIC} Status for {RESET}{BOLD}ALL{RESET}{ITALIC} projects {RESET}{DIM} ======= \n{RESET}{DIM_ITALIC}\n  NOW: {RESET}", end="")
    else:
        print(f"{DIM}\n ======={RESET}{ITALIC} Status for project: {RESET}{BOLD}{display_name}{RESET}{DIM} ======= \n{RESET}{DIM_ITALIC}\n  NOW: {RESET}", end="")

    if running:
        r=running[0]
        dur=format_duration(compute_duration(r, now))
        if is_all:
            print(f"{BOLD_GREEN}{r['description']}{RESET}{DIM_ITALIC} on {RESET}{ITALIC}{r['project']}{RESET}{DIM} ...... {RESET}{BOLD}{dur}{RESET}{DIM}\n\n{RESET}{ITALIC} {RESET}{DIM_ITALIC} Today......................... {RESET}{BOLD}{format_duration(today_total)}{RESET}{ITALIC}\n{RESET}{ITALIC} {RESET}{DIM_ITALIC} Current week.................. {RESET}{BOLD}{format_duration(week_total)}{RESET}{ITALIC}\n{RESET}{ITALIC} {RESET}{DIM_ITALIC} Current month................. {RESET}{BOLD}{format_duration(month_total)}{RESET}{ITALIC}\n{RESET}\n")
        else:
            print(f"{BOLD_GREEN}{r['description']}{RESET}{DIM} ...... {RESET}{BOLD}{dur}{RESET}{DIM}\n\n{RESET}{ITALIC} {RESET}{DIM_ITALIC} Today......................... {RESET}{BOLD}{format_duration(today_total)}{RESET}{ITALIC}\n{RESET}{ITALIC} {RESET}{DIM_ITALIC} Current week.................. {RESET}{BOLD}{format_duration(week_total)}{RESET}{ITALIC}\n{RESET}{ITALIC} {RESET}{DIM_ITALIC} Current month................. {RESET}{BOLD}{format_duration(month_total)}{RESET}{ITALIC}\n{RESET}\n")
    else:
        print(f"{BOLD} NO Activity\n\n{RESET}{ITALIC} {RESET}{DIM_ITALIC} Today......................... {RESET}{BOLD}{format_duration(today_total)}{RESET}{ITALIC}\n{RESET}{ITALIC} {RESET}{DIM_ITALIC} Current week.................. {RESET}{BOLD}{format_duration(week_total)}{RESET}{ITALIC}\n{RESET}{ITALIC} {RESET}{DIM_ITALIC} Current month................. {RESET}{BOLD}{format_duration(month_total)}{RESET}{ITALIC}\n{RESET}\n")

def cmd_edit(args):
