#!/usr/bin/env python3
import argparse
import sys
import os
import re
import datetime
from collections import defaultdict

ANSI_UNDERLINE = "\x1b[4m"
ANSI_BOLD = "\x1b[1m"
ANSI_RESET = "\x1b[0m"
ANSI_DIM = "\x1b[2m"
ANSI_ITALIC = "\x1b[3m"
ANSI_GREEN = "\x1b[32m"
ANSI_BOLD_GREEN = "\x1b[1;32m"

NBSP = "\xa0"
VERSION = "bartib 1.1.0"

def escape_str(s):
    return s.replace("\\", "\\\\").replace("|", "\\|")

def unescape_str(s):
    res=[]
    i=0
    while i < len(s):
        c=s[i]
        if c=="\\" and i+1 < len(s):
            res.append(s[i+1])
            i+=2
        else:
            if c=="\\":
                res.append(c)
                i+=1
            else:
                res.append(c)
                i+=1
    return "".join(res)

def split_escaped(s):
    parts=[]
    cur=[]
    i=0
    while i < len(s):
        c=s[i]
        if c=="|":
            cnt=0
            j=len(cur)-1
            while j>=0 and cur[j]=="\\":
                cnt+=1
                j-=1
            if cnt%2==1:
                cur.append(c)
            else:
                parts.append("".join(cur))
                cur=[]
            i+=1
        else:
            cur.append(c)
            i+=1
    parts.append("".join(cur))
    return parts

def parse_date_str(date_str):
    date_str=date_str.strip()
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", date_str):
        return None, "invalid_chars"
    try:
        dt=datetime.date.fromisoformat(date_str)
        return dt, None
    except:
        return None, "out_of_range"

def parse_date_with_warning(date_str, arg_label):
    dt, reason = parse_date_str(date_str)
