        else:
            print(f'Can not parse "{date_str}" as date. Argument for {arg_label} is ignored (input is out of range)')
        return None
    return dt

def parse_time_str(time_str):
    time_str=time_str.strip()
    if not re.fullmatch(r"\d{1,2}:\d{2}", time_str):
        # check if numeric
        if re.fullmatch(r"\d+:\d+", time_str):
            try:
                h,m=map(int,time_str.split(":"))
                if not (0<=h<=23 and 0<=m<=59):
                    return None, "out_of_range"
            except:
                pass
            return None, "invalid_chars"
        else:
            return None, "invalid_chars"
    try:
        h,m=map(int,time_str.split(":"))
        if not (0<=h<=23 and 0<=m<=59):
            return None, "out_of_range"
        return (h,m), None
    except:
        return None, "invalid_chars"

def parse_time_with_warning(time_str):
    res, reason = parse_time_str(time_str)
    if res is None:
        if reason=="out_of_range":
            print(f'Can not parse "{time_str}" as time. Argument for -t/--time is ignored (input is out of range)')
        else:
            print(f'Can not parse "{time_str}" as time. Argument for -t/--time is ignored (input contains invalid characters)')
        return None
    return res

def parse_round_str(round_str):
    round_str=round_str.strip()
    m=re.fullmatch(r"(\d+)([mh])", round_str)
    if not m:
        return None
    val=int(m.group(1))
    unit=m.group(2)
    if unit=="m":
        return datetime.timedelta(minutes=val)
    else:
        return datetime.timedelta(hours=val)

def round_datetime(dt, round_delta):
    delta_seconds=int(round_delta.total_seconds())
    midnight=dt.replace(hour=0,minute=0,second=0,microsecond=0)
    secs_since_midnight=(dt-midnight).total_seconds()
    remainder=secs_since_midnight % delta_seconds
    if remainder*2 < delta_seconds:
        rounded_secs=secs_since_midnight - remainder
    else:
        rounded_secs=secs_since_midnight + (delta_seconds - remainder)
    rounded_dt=midnight+datetime.timedelta(seconds=rounded_secs)
    return rounded_dt

