    filepath=parse_file_arg(args)
    all_entries, errors = load_activities_or_error(filepath, False)
    for err in errors:
        print(f"Warning: Ignoring line {err['line_num']}. Please see `bartib check` for further information")
    valid=[a for a in all_entries if a['valid']]
    running=[a for a in valid if a['end'] is None]
    if not running:
        print("No Activity is currently running")
        return
    max_desc=max(len(a['description']) for a in running)
    max_proj=max(len(a['project']) for a in running)
    desc_width=max(len("Description"), max_desc)
    proj_width=max(len("Project"), max_proj)
    started_width=max(len("Started At"), 16)
    duration_width=max(len("Duration"), 6)
    def pad(s,w):
        return s + NBSP*(w - len(s)) if len(s) < w else s
    print("")
    print(f"{underline(pad('Started At', started_width))} {underline(pad('Description', desc_width))} {underline(pad('Project', proj_width))} {underline(pad('Duration', duration_width))} ")
    now=get_now()
    for a in running:
        start_str=a['start'].strftime("%Y-%m-%d %H:%M")
        dur_str=format_duration(compute_duration(a, now))
        print(f"{pad(start_str, started_width)} {pad(a['description'], desc_width)} {pad(a['project'], proj_width)} {pad(dur_str, duration_width)} ")
    print("")

