        else:
            print(f"{BOLD_GREEN}{r['description']}{RESET}{DIM} ...... {RESET}{BOLD}{dur}{RESET}{DIM}\n\n{RESET}{ITALIC} {RESET}{DIM_ITALIC} Today......................... {RESET}{BOLD}{format_duration(today_total)}{RESET}{ITALIC}\n{RESET}{ITALIC} {RESET}{DIM_ITALIC} Current week.................. {RESET}{BOLD}{format_duration(week_total)}{RESET}{ITALIC}\n{RESET}{ITALIC} {RESET}{DIM_ITALIC} Current month................. {RESET}{BOLD}{format_duration(month_total)}{RESET}{ITALIC}\n{RESET}\n", end="")
    else:
        print(f"{BOLD} NO Activity\n\n{RESET}{ITALIC} {RESET}{DIM_ITALIC} Today......................... {RESET}{BOLD}{format_duration(today_total)}{RESET}{ITALIC}\n{RESET}{ITALIC} {RESET}{DIM_ITALIC} Current week.................. {RESET}{BOLD}{format_duration(week_total)}{RESET}{ITALIC}\n{RESET}{ITALIC} {RESET}{DIM_ITALIC} Current month................. {RESET}{BOLD}{format_duration(month_total)}{RESET}{ITALIC}\n{RESET}\n", end="")

