    else:
        start_time=get_now()
    all_entries, _, _ = read_file(filepath)
    valid=[a for a in all_entries if a['valid']]
    valid_sorted=sorted(valid, key=lambda x: x['start'], reverse=True)
    seen=set()
    deduped=[]
    for a in valid_sorted:
        k=(a['description'], a['project'])
        if k not in seen:
            seen.add(k)
            deduped.append(a)
    if not deduped:
        print("Error: No activity has been started before.", file=sys.stderr)
        sys.exit(1)
    try:
        num=int(args.number) if args.number is not None else 0
    except:
        num=0
