import argparse, sys, os, re, datetime
from collections import defaultdict

ANSI_UNDERLINE="\x1b[4m"
ANSI_BOLD="\x1b[1m"
ANSI_RESET="\x1b[0m"
ANSI_DIM="\x1b[2m"
ANSI_ITALIC="\x1b[3m"
ANSI_GREEN="\x1b[32m"
ANSI_BOLD_GREEN="\x1b[1;32m"
NBSP="\xa0"
