            from_filter=df
    if getattr(args, 'to_date', None):
        df, reason = parse_date_str(args.to_date)
        if df is None:
            if reason=="invalid_chars":
                print(f'Can not parse "{args.to_date}" as date. Argument for --to is ignored (input contains invalid characters)')
            else:
                print(f'Can not parse "{args.to_date}" as date. Argument for --to is ignored (input is out of range)')
        else:
            to_filter=df
    filtered=valid_sorted
    if getattr(args, 'today', False):
        filtered=[a for a in filtered if a['start'].date()==today]
    if getattr(args, 'yesterday', False):
        filtered=[a for a in filtered if a['start'].date()==yesterday]
    if getattr(args, 'current_week', False):
        filtered=[a for a in filtered if monday_current <= a['start'].date() <= sunday_current]
    if getattr(args, 'last_week', False):
        filtered=[a for a in filtered if monday_last <= a['start'].date() <= sunday_last]
    if date_filter:
        filtered=[a for a in filtered if a['start'].date()==date_filter]
    if from_filter:
        filtered=[a for a in filtered if a['start'].date() >= from_filter]
    if to_filter:
        filtered=[a for a in filtered if a['start'].date() <= to_filter]
    if getattr(args, 'project', None):
        filtered=[a for a in filtered if a['project']==args.project]
    args._valid_date_filter=valid_date_filter
    return filtered

def apply_rounding(activities, round_arg):
    if not round_arg:
        return activities, None
    round_delta=parse_round_str(round_arg)
    if round_delta is None:
        stripped=round_arg.strip()
        if stripped and stripped[0].isdigit():
            print(f'Can not parse "{round_arg}" as duration. Argument for --round is ignored')
        return activities, None
    rounded=[]
    for a in activities:
        new_a=a.copy()
        new_a['original_start']=a['start']
        new_a['original_end']=a['end']
        new_a['is_running_original']=a['end'] is None
        new_a['start']=round_datetime(a['start'], round_delta)
        if a['end']:
            new_a['end']=round_datetime(a['end'], round_delta)
        else:
            now=get_now()
            new_a['end']=round_datetime(now, round_delta)
        rounded.append(new_a)
    return rounded, round_delta

def compute_duration(activity, now=None):
    if now is None:
        now=get_now()
    start=activity['start']
    end=activity['end'] if activity['end'] else now
    return (end-start).total_seconds()

def underline(s):
    return f"{ANSI_UNDERLINE}{s}{ANSI_RESET}"

def cmd_list(args):
    filepath=parse_file_arg(args)
    all_entries, errors = load_activities_or_error(filepath, False)
    for err in errors:
        print(f"Warning: Ignoring line {err['line_num']}. Please see `bartib check` for further information")
    filtered=filter_activities(all_entries, args)
    for a in filtered:
        a['is_running_original']=a['end'] is None
    rounded, _ = apply_rounding(filtered, getattr(args, 'round', None))
    if getattr(args, 'number', None):
        try:
            n=int(args.number)
            if n < len(rounded):
                rounded=rounded[-n:]
        except:
            pass
    if not rounded:
        print("No activity to display")
        return
    grouping_disabled=False
    if getattr(args, 'no_grouping', False):
        grouping_disabled=True
    if getattr(args, 'today', False) or getattr(args, 'yesterday', False) or getattr(args, '_valid_date_filter', False):
        grouping_disabled=True
    max_desc=max(len(a['description']) for a in rounded) if rounded else 0
    max_proj=max(len(a['project']) for a in rounded) if rounded else 0
    desc_width=max(len("Description"), max_desc)
    proj_width=max(len("Project"), max_proj)
    if grouping_disabled and getattr(args, 'no_grouping', False):
        started_width=max(len("Started"), 16)
    else:
        started_width=max(len("Started"), 5)
    stopped_width=max(len("Stopped"), 5)
    now=get_now()
    dur_strs=[format_duration(compute_duration(a, now)) for a in rounded]
    max_dur=max(len(s) for s in dur_strs) if dur_strs else 0
    duration_width=max(len("Duration"), max_dur)
    def pad(s,w):
        return s + NBSP*(w - len(s)) if len(s) < w else s
    if grouping_disabled and getattr(args, 'no_grouping', False):
        print("")
        print(f"{underline(pad('Started', started_width))} {underline(pad('Stopped', stopped_width))} {underline(pad('Description', desc_width))} {underline(pad('Project', proj_width))} {underline(pad('Duration', duration_width))} ")
    else:
        print("")
        print(f"{underline(pad('Started', started_width))} {underline(pad('Stopped', stopped_width))} {underline(pad('Description', desc_width))} {underline(pad('Project', proj_width))} {underline(pad('Duration', duration_width))} ")
    if not grouping_disabled:
        groups=defaultdict(list)
        for a in rounded:
            groups[a['start'].date()].append(a)
        for date_key in sorted(groups.keys()):
            group_acts=groups[date_key]
            total_secs=sum(compute_duration(a, now) for a in group_acts)
            total_str=format_duration(total_secs)
            print("")
            print(f"{ANSI_BOLD}{date_key}\t{total_str}{ANSI_RESET}")
            for a in group_acts:
                start_str=a['start'].strftime("%H:%M")
                end_str="-" if a.get('is_running_original') else (a['end'].strftime("%H:%M") if a['end'] else "-")
                started_padded=pad(start_str, started_width)
                stopped_padded=pad(end_str, stopped_width)
                desc_padded=pad(a['description'], desc_width)
                proj_padded=pad(a['project'], proj_width)
                dur_padded=pad(format_duration(compute_duration(a, now)), duration_width)
                if a.get('is_running_original'):
                    print(f"{ANSI_GREEN}{started_padded}{ANSI_RESET} {ANSI_GREEN}{stopped_padded}{ANSI_RESET} {ANSI_GREEN}{desc_padded}{ANSI_RESET} {ANSI_GREEN}{proj_padded}{ANSI_RESET} {ANSI_GREEN}{dur_padded}{ANSI_RESET} ")
                else:
                    print(f"{started_padded} {stopped_padded} {desc_padded} {proj_padded} {dur_padded} ")
        print("")
    else:
        if getattr(args, 'no_grouping', False):
            for a in rounded:
                start_full=a['start'].strftime("%Y-%m-%d %H:%M")
                end_str="-" if a.get('is_running_original') else (a['end'].strftime("%H:%M") if a['end'] else "-")
                started_padded=pad(start_full, started_width)
                stopped_padded=pad(end_str, stopped_width)
                desc_padded=pad(a['description'], desc_width)
                proj_padded=pad(a['project'], proj_width)
                dur_padded=pad(format_duration(compute_duration(a, now)), duration_width)
                if a.get('is_running_original'):
                    print(f"{ANSI_GREEN}{started_padded}{ANSI_RESET} {ANSI_GREEN}{stopped_padded}{ANSI_RESET} {ANSI_GREEN}{desc_padded}{ANSI_RESET} {ANSI_GREEN}{proj_padded}{ANSI_RESET} {ANSI_GREEN}{dur_padded}{ANSI_RESET} ")
                else:
                    print(f"{started_padded} {stopped_padded} {desc_padded} {proj_padded} {dur_padded} ")
            print("")
        else:
            for a in rounded:
                start_str=a['start'].strftime("%H:%M")
                end_str="-" if a.get('is_running_original') else (a['end'].strftime("%H:%M") if a['end'] else "-")
                started_padded=pad(start_str, started_width)
                stopped_padded=pad(end_str, stopped_width)
                desc_padded=pad(a['description'], desc_width)
                proj_padded=pad(a['project'], proj_width)
                dur_padded=pad(format_duration(compute_duration(a, now)), duration_width)
                if a.get('is_running_original'):
                    print(f"{ANSI_GREEN}{started_padded}{ANSI_RESET} {ANSI_GREEN}{stopped_padded}{ANSI_RESET} {ANSI_GREEN}{desc_padded}{ANSI_RESET} {ANSI_GREEN}{proj_padded}{ANSI_RESET} {ANSI_GREEN}{dur_padded}{ANSI_RESET} ")
                else:
                    print(f"{started_padded} {stopped_padded} {desc_padded} {proj_padded} {dur_padded} ")
            print("")

def cmd_report(args):
    filepath=parse_file_arg(args)
    all_entries, errors = load_activities_or_error(filepath, False)
    for err in errors:
        print(f"Warning: Ignoring line {err['line_num']}. Please see `bartib check` for further information")
    filtered=filter_activities(all_entries, args)
    for a in filtered:
        a['is_running_original']=a['end'] is None
    rounded, _ = apply_rounding(filtered, getattr(args, 'round', None))
    if not rounded:
        print(f"\n{ANSI_BOLD}Total <1m{ANSI_RESET}\n")
        return
    now=get_now()
    proj_dict=defaultdict(list)
    for a in rounded:
        proj_dict[a['project']].append(a)
    max_len=len("Total")
    for proj, acts in proj_dict.items():
        max_len=max(max_len, len(proj))
        desc_groups=defaultdict(list)
        for act in acts:
            desc_groups[act['description']].append(act)
        for desc in desc_groups:
            max_len=max(max_len, len(desc)+4)
    sorted_projects=sorted(proj_dict.keys())
    total_all=0
    for proj in sorted_projects:
        acts=proj_dict[proj]
        proj_total=sum(compute_duration(a, now) for a in acts)
        total_all+=proj_total
        dur_str=format_duration(proj_total)
        dots="."*(max_len - len(proj)) if max_len>len(proj) else ""
        print(f"\n{ANSI_BOLD}{proj}{dots} {dur_str}{ANSI_RESET}")
        desc_groups=defaultdict(list)
        for act in acts:
            desc_groups[act['description']].append(act)
        for desc in sorted(desc_groups.keys()):
            d_acts=desc_groups[desc]
            d_total=sum(compute_duration(a, now) for a in d_acts)
            d_str=format_duration(d_total)
            key="    "+desc
            dots2="."*(max_len - len(key)) if max_len>len(key) else ""
            print(f"{key}{dots2} {d_str}")
    total_str=format_duration(total_all)
    dots_total="."*(max_len - len("Total")) if max_len>len("Total") else ""
    print(f"\n{ANSI_BOLD}Total{dots_total} {total_str}{ANSI_RESET}\n")

