    max_desc=max(len(a['description']) for a in deduped) if deduped else 0
    max_proj=max(len(a['project']) for a in deduped) if deduped else 0
    desc_width=max(len("Description"), max_desc)
    proj_width=max(len("Project"), max_proj)
    def pad(s,w):
        return s + NBSP*(w - len(s)) if len(s) < w else s
    print("")
    print(f"{underline(pad(' #'+NBSP,3))} {underline(pad('Description', desc_width))} {underline(pad('Project', proj_width))} ")
    display=list(reversed(deduped))
    for pos, act in enumerate(display):
        idx=len(deduped)-1 - pos
