def write_entries(filepath, entries):
    with open(filepath, 'w', encoding='utf-8') as f:
        for e in entries:
            if not e['valid']:
                f.write(e['raw_line'] + "\n")
            else:
                if e.get('write_as')=='stopped_trimmed':
                    s=e['start'].strftime("%Y-%m-%d %H:%M")
                    en=e['end'].strftime("%Y-%m-%d %H:%M")
                    f.write(f"{s} - {en} | {escape_str(e['project'])} | {escape_str(e['description'])}\n")
                elif e.get('write_as') in ('running_new','running_preserve_changed'):
                    s=e['start'].strftime("%Y-%m-%d %H:%M")
                    f.write(f"{s} | {escape_str(e['project_raw_input'])} | {escape_str(e['description_raw_input'])}\n")
                else:
                    dt_raw=e['datetime_raw'].lstrip()
                    proj_raw=e['project_raw']
                    desc_raw=e['description_raw']
                    desc_rstrip=desc_raw.rstrip(" \t")
                    f.write(f"{dt_raw}|{proj_raw}|{desc_rstrip}\n")

def cmd_start(args):
    filepath=parse_file_arg(args)
    if filepath is None:
        print("Error: Please specify a file with your activity log either as -f option or as BARTIB_FILE environment variable", file=sys.stderr)
        sys.exit(1)
    if args.time:
        pt=parse_time_with_warning(args.time)
        if pt:
            h,m=pt
            start_time=datetime.datetime.combine(get_today(), datetime.time(h,m))
        else:
            start_time=get_now()
    else:
        start_time=get_now()
    all_entries=[]
    if os.path.exists(filepath):
        all_entries, _, _ = read_file(filepath)
    new_entries=[]
    for entry in all_entries:
        if not entry['valid']:
            new_entries.append(entry)
        else:
            if entry['end'] is None:
                print(f"Stopped activity: \"{entry['description']}\" ({entry['project']}) started at {entry['start'].strftime('%Y-%m-%d %H:%M')} ({format_duration((start_time - entry['start']).total_seconds())})")
                new_entries.append({'valid': True, 'line_num': entry['line_num'], 'start': entry['start'], 'end': start_time, 'project': entry['project'], 'description': entry['description'], 'write_as': 'stopped_trimmed'})
            else:
                new_entries.append(entry)
    new_entries.append({'valid': True, 'line_num': 0, 'start': start_time, 'end': None, 'project': args.project.strip(), 'description': args.description.strip(), 'project_raw_input': args.project, 'description_raw_input': args.description, 'write_as': 'running_new'})
    write_entries(filepath, new_entries)
    print(f"Started activity: \"{args.description}\" ({args.project}) at {start_time.strftime('%Y-%m-%d %H:%M')}")

def cmd_stop(args):
    filepath=parse_file_arg(args)
    if filepath is None:
        print("Error: Please specify a file with your activity log either as -f option or as BARTIB_FILE environment variable", file=sys.stderr)
        sys.exit(1)
    if not os.path.exists(filepath):
        print(f"Error: Could not read from file: {filepath}\n\nCaused by:\n    No such file or directory (os error 2)", file=sys.stderr)
        sys.exit(1)
    if args.time:
        pt=parse_time_with_warning(args.time)
        if pt:
            h,m=pt
            stop_time=datetime.datetime.combine(get_today(), datetime.time(h,m))
        else:
            stop_time=get_now()
