    running=[a for a in all_entries if a['valid'] and a['end'] is None]
    if not running:
        return
    new_entries=[]
    for entry in all_entries:
        if not entry['valid']:
            new_entries.append(entry)
        else:
            if entry['end'] is None:
                print(f"Canceled activity: \"{entry['description']}\" ({entry['project']}) started at {entry['start'].strftime('%Y-%m-%d %H:%M')}")
            else:
