#!/usr/bin/env python3
import argparse, sys, os, re, datetime
from collections import defaultdict

ANSI_UNDERLINE="\x1b[4m"
ANSI_BOLD="\x1b[1m"
ANSI_RESET="\x1b[0m"
ANSI_DIM="\x1b[2m"
ANSI_ITALIC="\x1b[3m"
ANSI_GREEN="\x1b[32m"
ANSI_BOLD_GREEN="\x1b[1;32m"
NBSP="\xa0"
VERSION="bartib 1.1.0"

def escape_str(s):
    return s.replace("\\", "\\\\").replace("|", "\\|")

def unescape_str(s):
    res=[]
    i=0
    while i < len(s):
        c=s[i]
        if c=="\\" and i+1 < len(s):
            res.append(s[i+1])
            i+=2
        else:
            if c=="\\":
                res.append(c)
                i+=1
            else:
                res.append(c)
                i+=1
    return "".join(res)

def split_escaped(s):
    parts=[]
    cur=[]
    i=0
    while i < len(s):
        c=s[i]
        if c=="|":
            cnt=0
            j=len(cur)-1
            while j>=0 and cur[j]=="\\":
                cnt+=1
                j-=1
            if cnt%2==1:
                cur.append(c)
            else:
                parts.append("".join(cur))
                cur=[]
            i+=1
        else:
            cur.append(c)
            i+=1
    parts.append("".join(cur))
    return parts

def parse_date_str(date_str):
    date_str=date_str.strip()
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", date_str):
        return None, "invalid_chars"
    try:
        dt=datetime.date.fromisoformat(date_str)
        return dt, None
    except:
        return None, "out_of_range"

def parse_time_str(time_str):
    time_str=time_str.strip()
    if not re.fullmatch(r"\d{1,2}:\d{2}", time_str):
        if re.fullmatch(r"\d+:\d+", time_str):
            try:
                h,m=map(int,time_str.split(":"))
                if not (0<=h<=23 and 0<=m<=59):
                    return None, "out_of_range"
            except:
                pass
            return None, "invalid_chars"
        else:
            return None, "invalid_chars"
    try:
        h,m=map(int,time_str.split(":"))
        if not (0<=h<=23 and 0<=m<=59):
            return None, "out_of_range"
        return (h,m), None
    except:
        return None, "invalid_chars"

def parse_time_with_warning(time_str):
    res, reason = parse_time_str(time_str)
    if res is None:
        if reason=="out_of_range":
            print(f'Can not parse "{time_str}" as time. Argument for -t/--time is ignored (input is out of range)')
        else:
            print(f'Can not parse "{time_str}" as time. Argument for -t/--time is ignored (input contains invalid characters)')
        return None
    return res

def parse_round_str(round_str):
    round_str=round_str.strip()
    m=re.fullmatch(r"(\d+)([mh])", round_str)
    if not m:
        return None
    val=int(m.group(1))
    unit=m.group(2)
    if unit=="m":
        return datetime.timedelta(minutes=val)
    else:
        return datetime.timedelta(hours=val)

def round_datetime(dt, round_delta):
    delta_seconds=int(round_delta.total_seconds())
    if delta_seconds==0:
        return dt
    midnight=dt.replace(hour=0,minute=0,second=0,microsecond=0)
    secs_since_midnight=(dt-midnight).total_seconds()
    remainder=secs_since_midnight % delta_seconds
    if remainder*2 < delta_seconds:
        rounded_secs=secs_since_midnight - remainder
    else:
        rounded_secs=secs_since_midnight + (delta_seconds - remainder)
    return midnight+datetime.timedelta(seconds=rounded_secs)

def format_duration(delta_seconds):
    total_seconds=int(delta_seconds)
    if total_seconds < 60:
        return "<1m"
    total_minutes=total_seconds//60
    hours=total_minutes//60
    minutes=total_minutes%60
    if hours==0:
        return f"{minutes:02d}m"
    else:
        return f"{hours}h {minutes:02d}m"

def parse_activity_line(line, line_num):
    raw_line=line
    if raw_line.strip()=="":
        return {'valid': False, 'raw_line': raw_line, 'line_num': line_num, 'error_type': 'activity', 'error_msg': f"could not parse activity (Line: {line_num})", 'line_content': raw_line}
    parts=split_escaped(raw_line)
    datetime_raw=parts[0] if len(parts)>=1 else ""
    project_raw=parts[1] if len(parts)>=2 else ""
    description_raw=parts[2] if len(parts)>=3 else ""
    dt_str=datetime_raw.strip()
    strict_two=r"^\s*(\d{4}-\d{2}-\d{2})\s+(\d{1,2}):(\d{2})\s+-\s+(\d{4}-\d{2}-\d{2})\s+(\d{1,2}):(\d{2})\s*$"
    loose_two=r"^\s*\d{4}-\d{2}-\d{2}\s+\d{1,2}:\d{2}\s*-\s*\d{4}-\d{2}-\d{2}\s+\d{1,2}:\d{2}\s*$"
    strict_one=r"^\s*(\d{4}-\d{2}-\d{2})\s+(\d{1,2}):(\d{2})\s*$"
    if re.match(strict_two, dt_str):
        m=re.match(strict_two, dt_str)
        try:
            start_date_str=m.group(1)
            sh=int(m.group(2)); sm=int(m.group(3))
            end_date_str=m.group(4)
            eh=int(m.group(5)); em=int(m.group(6))
            start_dt=datetime.datetime.strptime(f"{start_date_str} {sh:02d}:{sm:02d}", "%Y-%m-%d %H:%M")
            end_dt=datetime.datetime.strptime(f"{end_date_str} {eh:02d}:{em:02d}", "%Y-%m-%d %H:%M")
            proj_unesc=unescape_str(project_raw)
            desc_unesc=unescape_str(description_raw)
            return {'valid': True, 'raw_line': raw_line, 'line_num': line_num, 'start': start_dt, 'end': end_dt, 'project': proj_unesc.strip(), 'description': desc_unesc.strip(), 'project_raw': project_raw, 'description_raw': description_raw, 'datetime_raw': datetime_raw, 'is_running': False}
        except:
            return {'valid': False, 'raw_line': raw_line, 'line_num': line_num, 'error_type': 'date', 'error_msg': f"could not parse date or time of activity (Line: {line_num})", 'line_content': raw_line}
    else:
        if re.match(loose_two, dt_str):
            return {'valid': False, 'raw_line': raw_line, 'line_num': line_num, 'error_type': 'date', 'error_msg': f"could not parse date or time of activity (Line: {line_num})", 'line_content': raw_line}
        m1=re.match(strict_one, dt_str)
        if m1:
            try:
                date_str=m1.group(1)
                h=int(m1.group(2)); mm=int(m1.group(3))
                dt=datetime.datetime.strptime(f"{date_str} {h:02d}:{mm:02d}", "%Y-%m-%d %H:%M")
                proj_unesc=unescape_str(project_raw)
                desc_unesc=unescape_str(description_raw)
                return {'valid': True, 'raw_line': raw_line, 'line_num': line_num, 'start': dt, 'end': None, 'project': proj_unesc.strip(), 'description': desc_unesc.strip(), 'project_raw': project_raw, 'description_raw': description_raw, 'datetime_raw': datetime_raw, 'is_running': True}
            except:
                return {'valid': False, 'raw_line': raw_line, 'line_num': line_num, 'error_type': 'date', 'error_msg': f"could not parse date or time of activity (Line: {line_num})", 'line_content': raw_line}
        if re.match(r"^\s*\d{4}-\d{2}-\d{2}\s+\d{1,2}:\d{2}\s*$", dt_str):
            return {'valid': False, 'raw_line': raw_line, 'line_num': line_num, 'error_type': 'date', 'error_msg': f"could not parse date or time of activity (Line: {line_num})", 'line_content': raw_line}
        return {'valid': False, 'raw_line': raw_line, 'line_num': line_num, 'error_type': 'activity', 'error_msg': f"could not parse activity (Line: {line_num})", 'line_content': raw_line}

def read_file(filepath):
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            lines=f.readlines()
    except Exception as e:
        return None, None, f"Could not read from file: {filepath}\n\nCaused by:\n    {e}"
    activities=[]
    errors=[]
    for idx, line in enumerate(lines, start=1):
        line_no_nl=line.rstrip("\n")
        parsed=parse_activity_line(line_no_nl, idx)
        activities.append(parsed)
        if not parsed['valid']:
            errors.append(parsed)
    return activities, errors, None

def get_now():
    return datetime.datetime.now().replace(second=0, microsecond=0)

def get_today():
    return datetime.date.today()

def parse_file_arg(args):
    if args.file:
        return args.file
    env_file=os.environ.get("BARTIB_FILE")
    if env_file:
        return env_file
    return None

def load_activities_or_error(filepath, allow_missing=False):
    if filepath is None:
        print("Error: Please specify a file with your activity log either as -f option or as BARTIB_FILE environment variable", file=sys.stderr)
        sys.exit(1)
    if not os.path.exists(filepath):
        if allow_missing:
            return [], []
        else:
            print(f"Error: Could not read from file: {filepath}\n\nCaused by:\n    No such file or directory (os error 2)", file=sys.stderr)
            sys.exit(1)
    acts, errs, msg = read_file(filepath)
    if msg:
        print(f"Error: {msg}", file=sys.stderr)
        sys.exit(1)
    return acts, errs

def filter_activities(activities_all, args):
    valid=[a for a in activities_all if a['valid']]
    valid_sorted=sorted(valid, key=lambda x: x['start'])
    today=get_today()
    yesterday=today - datetime.timedelta(days=1)
    monday_current=today - datetime.timedelta(days=today.weekday())
    sunday_current=monday_current + datetime.timedelta(days=6)
    monday_last=monday_current - datetime.timedelta(days=7)
    sunday_last=monday_current - datetime.timedelta(days=1)
    date_filter=None
    from_filter=None
    to_filter=None
    valid_date_filter=False
    if getattr(args, 'date', None):
        df, reason = parse_date_str(args.date)
        if df is None:
            if reason=="invalid_chars":
                print(f'Can not parse "{args.date}" as date. Argument for -d/--date is ignored (input contains invalid characters)')
            else:
                print(f'Can not parse "{args.date}" as date. Argument for -d/--date is ignored (input is out of range)')
        else:
            date_filter=df
            valid_date_filter=True
    if getattr(args, 'from_date', None):
        df, reason = parse_date_str(args.from_date)
        if df is None:
            if reason=="invalid_chars":
                print(f'Can not parse "{args.from_date}" as date. Argument for --from is ignored (input contains invalid characters)')
            else:
                print(f'Can not parse "{args.from_date}" as date. Argument for --from is ignored (input is out of range)')
        else:
            from_filter=df
    if getattr(args, 'to_date', None):
        df, reason = parse_date_str(args.to_date)
        if df is None:
            if reason=="invalid_chars":
                print(f'Can not parse "{args.to_date}" as date. Argument for --to is ignored (input contains invalid characters)')
            else:
                print(f'Can not parse "{args.to_date}" as date. Argument for --to is ignored (input is out of range)')
        else:
            to_filter=df
    filtered=valid_sorted
    if getattr(args, 'today', False):
        filtered=[a for a in filtered if a['start'].date()==today]
    if getattr(args, 'yesterday', False):
        filtered=[a for a in filtered if a['start'].date()==yesterday]
    if getattr(args, 'current_week', False):
        filtered=[a for a in filtered if monday_current <= a['start'].date() <= sunday_current]
    if getattr(args, 'last_week', False):
        filtered=[a for a in filtered if monday_last <= a['start'].date() <= sunday_last]
    if date_filter:
        filtered=[a for a in filtered if a['start'].date()==date_filter]
    if from_filter:
        filtered=[a for a in filtered if a['start'].date() >= from_filter]
    if to_filter:
        filtered=[a for a in filtered if a['start'].date() <= to_filter]
    if getattr(args, 'project', None):
        filtered=[a for a in filtered if a['project']==args.project]
    args._valid_date_filter=valid_date_filter
    return filtered

def apply_rounding(activities, round_arg):
    if not round_arg:
        return activities, None
    round_delta=parse_round_str(round_arg)
    if round_delta is None:
        stripped=round_arg.strip()
        if stripped and stripped[0].isdigit():
            print(f'Can not parse "{round_arg}" as duration. Argument for --round is ignored')
        return activities, None
    rounded=[]
    for a in activities:
        new_a=a.copy()
        new_a['original_start']=a['start']
        new_a['original_end']=a['end']
        new_a['is_running_original']=a['end'] is None
        new_a['start']=round_datetime(a['start'], round_delta)
        if a['end']:
            new_a['end']=round_datetime(a['end'], round_delta)
        else:
            now=get_now()
            new_a['end']=round_datetime(now, round_delta)
        rounded.append(new_a)
    return rounded, round_delta

def compute_duration(activity, now=None):
    if now is None:
        now=get_now()
    start=activity['start']
    end=activity['end'] if activity['end'] else now
    return (end-start).total_seconds()

def underline(s):
    return f"{ANSI_UNDERLINE}{s}{ANSI_RESET}"

def cmd_list(args):
    filepath=parse_file_arg(args)
    all_entries, errors = load_activities_or_error(filepath, False)
    for err in errors:
        print(f"Warning: Ignoring line {err['line_num']}. Please see `bartib check` for further information")
    filtered=filter_activities(all_entries, args)
    for a in filtered:
        a['is_running_original']=a['end'] is None
    rounded, _ = apply_rounding(filtered, getattr(args, 'round', None))
    if getattr(args, 'number', None):
        try:
            n=int(args.number)
            if n < len(rounded):
                rounded=rounded[-n:]
        except:
            pass
    if not rounded:
        print("No activity to display")
        return
    grouping_disabled=False
    if getattr(args, 'no_grouping', False):
        grouping_disabled=True
    if getattr(args, 'today', False) or getattr(args, 'yesterday', False) or getattr(args, '_valid_date_filter', False):
        grouping_disabled=True
    max_desc=max(len(a['description']) for a in rounded) if rounded else 0
    max_proj=max(len(a['project']) for a in rounded) if rounded else 0
    desc_width=max(len("Description"), max_desc)
    proj_width=max(len("Project"), max_proj)
    if grouping_disabled and getattr(args, 'no_grouping', False):
        started_width=max(len("Started"), 16)
    else:
        started_width=max(len("Started"), 5)
    stopped_width=max(len("Stopped"), 5)
    now=get_now()
    dur_strs=[format_duration(compute_duration(a, now)) for a in rounded]
    max_dur=max(len(s) for s in dur_strs) if dur_strs else 0
    duration_width=max(len("Duration"), max_dur)
    def pad(s,w):
        return s + NBSP*(w - len(s)) if len(s) < w else s
    if grouping_disabled and getattr(args, 'no_grouping', False):
        print("")
        print(f"{underline(pad('Started', started_width))} {underline(pad('Stopped', stopped_width))} {underline(pad('Description', desc_width))} {underline(pad('Project', proj_width))} {underline(pad('Duration', duration_width))} ")
    else:
        print("")
        print(f"{underline(pad('Started', started_width))} {underline(pad('Stopped', stopped_width))} {underline(pad('Description', desc_width))} {underline(pad('Project', proj_width))} {underline(pad('Duration', duration_width))} ")
    if not grouping_disabled:
        groups=defaultdict(list)
        for a in rounded:
            groups[a['start'].date()].append(a)
        for date_key in sorted(groups.keys()):
            group_acts=groups[date_key]
            total_secs=sum(compute_duration(a, now) for a in group_acts)
            total_str=format_duration(total_secs)
            print("")
            print(f"{ANSI_BOLD}{date_key}\t{total_str}{ANSI_RESET}")
            for a in group_acts:
                start_str=a['start'].strftime("%H:%M")
                end_str="-" if a.get('is_running_original') else (a['end'].strftime("%H:%M") if a['end'] else "-")
                started_padded=pad(start_str, started_width)
                stopped_padded=pad(end_str, stopped_width)
                desc_padded=pad(a['description'], desc_width)
                proj_padded=pad(a['project'], proj_width)
                dur_padded=pad(format_duration(compute_duration(a, now)), duration_width)
                if a.get('is_running_original'):
                    print(f"{ANSI_GREEN}{started_padded}{ANSI_RESET} {ANSI_GREEN}{stopped_padded}{ANSI_RESET} {ANSI_GREEN}{desc_padded}{ANSI_RESET} {ANSI_GREEN}{proj_padded}{ANSI_RESET} {ANSI_GREEN}{dur_padded}{ANSI_RESET} ")
                else:
                    print(f"{started_padded} {stopped_padded} {desc_padded} {proj_padded} {dur_padded} ")
        print("")
    else:
        if getattr(args, 'no_grouping', False):
            for a in rounded:
                start_full=a['start'].strftime("%Y-%m-%d %H:%M")
                end_str="-" if a.get('is_running_original') else (a['end'].strftime("%H:%M") if a['end'] else "-")
                started_padded=pad(start_full, started_width)
                stopped_padded=pad(end_str, stopped_width)
                desc_padded=pad(a['description'], desc_width)
                proj_padded=pad(a['project'], proj_width)
                dur_padded=pad(format_duration(compute_duration(a, now)), duration_width)
                if a.get('is_running_original'):
                    print(f"{ANSI_GREEN}{started_padded}{ANSI_RESET} {ANSI_GREEN}{stopped_padded}{ANSI_RESET} {ANSI_GREEN}{desc_padded}{ANSI_RESET} {ANSI_GREEN}{proj_padded}{ANSI_RESET} {ANSI_GREEN}{dur_padded}{ANSI_RESET} ")
                else:
                    print(f"{started_padded} {stopped_padded} {desc_padded} {proj_padded} {dur_padded} ")
            print("")
        else:
            for a in rounded:
                start_str=a['start'].strftime("%H:%M")
                end_str="-" if a.get('is_running_original') else (a['end'].strftime("%H:%M") if a['end'] else "-")
                started_padded=pad(start_str, started_width)
                stopped_padded=pad(end_str, stopped_width)
                desc_padded=pad(a['description'], desc_width)
                proj_padded=pad(a['project'], proj_width)
                dur_padded=pad(format_duration(compute_duration(a, now)), duration_width)
                if a.get('is_running_original'):
                    print(f"{ANSI_GREEN}{started_padded}{ANSI_RESET} {ANSI_GREEN}{stopped_padded}{ANSI_RESET} {ANSI_GREEN}{desc_padded}{ANSI_RESET} {ANSI_GREEN}{proj_padded}{ANSI_RESET} {ANSI_GREEN}{dur_padded}{ANSI_RESET} ")
                else:
                    print(f"{started_padded} {stopped_padded} {desc_padded} {proj_padded} {dur_padded} ")
            print("")

def cmd_report(args):
    filepath=parse_file_arg(args)
    all_entries, errors = load_activities_or_error(filepath, False)
    for err in errors:
        print(f"Warning: Ignoring line {err['line_num']}. Please see `bartib check` for further information")
    filtered=filter_activities(all_entries, args)
    for a in filtered:
        a['is_running_original']=a['end'] is None
    rounded, _ = apply_rounding(filtered, getattr(args, 'round', None))
    if not rounded:
        print(f"\n{ANSI_BOLD}Total <1m{ANSI_RESET}\n")
        return
    now=get_now()
    proj_dict=defaultdict(list)
    for a in rounded:
        proj_dict[a['project']].append(a)
    max_len=len("Total")
    for proj, acts in proj_dict.items():
        max_len=max(max_len, len(proj))
        desc_groups=defaultdict(list)
        for act in acts:
            desc_groups[act['description']].append(act)
        for desc in desc_groups:
            max_len=max(max_len, len(desc)+4)
    sorted_projects=sorted(proj_dict.keys())
    total_all=0
    for proj in sorted_projects:
        acts=proj_dict[proj]
        proj_total=sum(compute_duration(a, now) for a in acts)
        total_all+=proj_total
        dur_str=format_duration(proj_total)
        dots="."*(max_len - len(proj)) if max_len>len(proj) else ""
        print(f"\n{ANSI_BOLD}{proj}{dots} {dur_str}{ANSI_RESET}")
        desc_groups=defaultdict(list)
        for act in acts:
            desc_groups[act['description']].append(act)
        for desc in sorted(desc_groups.keys()):
            d_acts=desc_groups[desc]
            d_total=sum(compute_duration(a, now) for a in d_acts)
            d_str=format_duration(d_total)
            key="    "+desc
            dots2="."*(max_len - len(key)) if max_len>len(key) else ""
            print(f"{key}{dots2} {d_str}")
    total_str=format_duration(total_all)
    dots_total="."*(max_len - len("Total")) if max_len>len("Total") else ""
    print(f"\n{ANSI_BOLD}Total{dots_total} {total_str}{ANSI_RESET}\n")

