        else:
            stop_time=get_now()
    else:
        stop_time=get_now()
    all_entries, _, _ = read_file(filepath)
    running=[a for a in all_entries if a['valid'] and a['end'] is None]
    if not running:
        return
    new_entries=[]
    for entry in all_entries:
        if not entry['valid']:
            new_entries.append(entry)
        else:
            if entry['end'] is None:
                print(f"Stopped activity: \"{entry['description']}\" ({entry['project']}) started at {entry['start'].strftime('%Y-%m-%d %H:%M')} ({format_duration((stop_time - entry['start']).total_seconds())})")
                new_entries.append({'valid': True, 'line_num': entry['line_num'], 'start': entry['start'], 'end': stop_time, 'project': entry['project'], 'description': entry['description'], 'write_as': 'stopped_trimmed'})
            else:
                new_entries.append(entry)
    write_entries(filepath, new_entries)

