def cmd_change(args):
    filepath=parse_file_arg(args)
    if filepath is None:
        print("Error: Please specify a file with your activity log either as -f option or as BARTIB_FILE environment variable", file=sys.stderr)
        sys.exit(1)
    if not os.path.exists(filepath):
        print(f"Error: Could not read from file: {filepath}\n\nCaused by:\n    No such file or directory (os error 2)", file=sys.stderr)
        sys.exit(1)
    new_start=None
    new_start_valid=False
    if args.time:
        pt=parse_time_with_warning(args.time)
        if pt:
            h,m=pt
            new_start=datetime.datetime.combine(get_today(), datetime.time(h,m))
            new_start_valid=True
    all_entries, _, _ = read_file(filepath)
    running=[a for a in all_entries if a['valid'] and a['end'] is None]
    if not running:
        return
    if args.time and not new_start_valid and args.project is None and args.description is None:
        return
    new_entries=[]
    for entry in all_entries:
        if not entry['valid']:
            new_entries.append(entry)
        else:
            if entry['end'] is None:
                proj_input=args.project if args.project is not None else entry['project']
                desc_input=args.description if args.description is not None else entry['description']
                start_dt=new_start if new_start_valid else entry['start']
                new_entries.append({'valid': True, 'line_num': entry['line_num'], 'start': start_dt, 'end': None, 'project': proj_input.strip(), 'description': desc_input.strip(), 'project_raw_input': proj_input, 'description_raw_input': desc_input, 'write_as': 'running_preserve_changed'})
                print(f"Changed activity: \"{desc_input}\" ({proj_input}) started at {start_dt.strftime('%Y-%m-%d %H:%M')}")
            else:
                new_entries.append(entry)
    write_entries(filepath, new_entries)

def cmd_continue(args):
    filepath=parse_file_arg(args)
    if filepath is None:
        print("Error: Please specify a file with your activity log either as -f option or as BARTIB_FILE environment variable", file=sys.stderr)
        sys.exit(1)
    if not os.path.exists(filepath):
        print(f"Error: Could not read from file: {filepath}\n\nCaused by:\n    No such file or directory (os error 2)", file=sys.stderr)
        sys.exit(1)
    if args.time:
        pt=parse_time_with_warning(args.time)
        if pt:
            h,m=pt
            start_time=datetime.datetime.combine(get_today(), datetime.time(h,m))
        else:
            start_time=get_now()
    else:
        start_time=get_now()
    all_entries, _, _ = read_file(filepath)
    valid=[a for a in all_entries if a['valid']]
    valid_sorted=sorted(valid, key=lambda x: x['start'], reverse=True)
    seen=set()
    deduped=[]
    for a in valid_sorted:
        k=(a['description'], a['project'])
        if k not in seen:
            seen.add(k)
            deduped.append(a)
    if not deduped:
        print("Error: No activity has been started before.", file=sys.stderr)
        sys.exit(1)
    try:
        num=int(args.number) if args.number is not None else 0
    except:
        num=0
    if num<0 or num>=len(deduped):
        print(f"Error: Less than {num} distinct activities have been logged yet", file=sys.stderr)
        sys.exit(1)
    selected=deduped[num]
    proj_input=args.project if args.project is not None else selected['project']
    desc_input=args.description if args.description is not None else selected['description']
    new_entries=[]
    for entry in all_entries:
        if not entry['valid']:
            new_entries.append(entry)
        else:
            if entry['end'] is None:
                print(f"Stopped activity: \"{entry['description']}\" ({entry['project']}) started at {entry['start'].strftime('%Y-%m-%d %H:%M')} ({format_duration((start_time - entry['start']).total_seconds())})")
                new_entries.append({'valid': True, 'line_num': entry['line_num'], 'start': entry['start'], 'end': start_time, 'project': entry['project'], 'description': entry['description'], 'write_as': 'stopped_trimmed'})
            else:
                new_entries.append(entry)
    new_entries.append({'valid': True, 'line_num': 0, 'start': start_time, 'end': None, 'project': proj_input.strip(), 'description': desc_input.strip(), 'project_raw_input': proj_input, 'description_raw_input': desc_input, 'write_as': 'running_new'})
    write_entries(filepath, new_entries)
    print(f"Started activity: \"{desc_input}\" ({proj_input}) at {start_time.strftime('%Y-%m-%d %H:%M')}")

